function arcPath(r, a0, a1) {
  var x0 = CX + r * Math.sin(a0), y0 = CY - r * Math.cos(a0);
  var x1 = CX + r * Math.sin(a1), y1 = CY - r * Math.cos(a1);
  var large = Math.abs(a1 - a0) > Math.PI ? 1 : 0;
  var sweep = a1 > a0 ? 1 : 0;
  return 'M ' + x0 + ' ' + y0 + ' A ' + r + ' ' + r + ' 0 ' + large + ' ' + sweep + ' ' + x1 + ' ' + y1;
}

function render() {
  var t1 = state.theta1;
  var s = state.n1 * Math.sin(t1) / state.n2;
  var TIR = s > 1;
  var th2 = TIR ? NaN : Math.asin(Math.max(-1, Math.min(1, s)));

  // incident ray: from upper-left (angle t1 left of normal)
