    refRay.plot(CX, CY, CX + RAYLEN * Math.sin(th2), CY + RAYLEN * Math.cos(th2)).opacity(1);
  } else { refRay.opacity(0); }

  // reflected: symmetric about normal
  rflRay.plot(CX, CY, CX + RAYLEN * Math.sin(t1), CY - RAYLEN * Math.cos(t1)).opacity(TIR ? 1 : 0);
  tirLabel.move(CX + 0.55 * RAYLEN * Math.sin(t1) - 60, CY - 0.55 * RAYLEN * Math.cos(t1) - 18).opacity(TIR ? 1 : 0);

