    .transform({ rotate: 90 - t1 * 180 / Math.PI + 180 - 90 + (90 - 90), origin: [CX - lm * RAYLEN * Math.sin(t1) - 26, CY - lm * RAYLEN * Math.cos(t1) - 30] });
  // simpler: rotate so text runs along the ray
  var angDeg = (90 - t1 * 180 / Math.PI);
  rdLabel.transform({ rotate: angDeg - 0 }, false);
  rdLabel.transform({ rotate: - (180 - (t1 * 180 / Math.PI) ) }, false); // run parallel up-left
