      .move(CX + 70 * Math.sin(th2 / 2) + 18, CY + 70 * Math.cos(th2 / 2) - 10);
  }

  // critical angle indicator
  if (state.n1 > state.n2) {
    var tc = Math.asin(state.n2 / state.n1);
    arcC.plot(arcPath(95, 0, -tc));
    tcLab.text('θc = ' + (tc * 180 / Math.PI).toFixed(1) + '°').move(CX - 95 * Math.sin(tc / 2) - 100, CY - 95 * Math.cos(tc / 2) - 40);
  } else { arcC.plot(''); tcLab.text(''); }
  window.__markRendered();
}

// Dragging the incident ray
