refRay.css('cursor', 'pointer');
rflRay.on('click', function () { showPopup('Reflected ray', 'Past the critical angle θc = arcsin(n₂/n₁), no real θ₂ exists — all light reflects totally inside the denser medium.'); });
rflRay.css('cursor', 'pointer');

